import {enchantVisual} from '../combat.js?v=10';
// Original art sheets. UV cropping is performed at runtime; original alpha is preserved.
export const visualAssets={hero:null,terrain:null,wolf:null,weapon:null,ready:false,loaded:0,errors:[]};
const entries=[['ruptorMotion','assets/ruptor-motion-v3.webp'],['attackMotion','assets/attacks-v3.webp'],['effects','assets/effects-v3.webp'],['classes','assets/classes-atlas-v2.webp'],['relics','assets/relics-atlas-v2.webp'],['arsenal','assets/arsenal-atlas-v2.webp'],['hero','assets/warrior-atlas-v1.webp'],['terrain','assets/garden-atlas-v1.webp'],['wolf','assets/wolf-atlas-v1.webp'],['weapon','assets/weapon-atlas-v1.webp']];
export const visualAssetsReady=Promise.all(entries.map(([key,url])=>new Promise(resolve=>{const image=new Image();image.onload=()=>{visualAssets[key]=image;visualAssets.loaded++;resolve(true);};image.onerror=()=>{visualAssets.errors.push(url);resolve(false);};image.src=url;}))).then(values=>{visualAssets.ready=values.every(Boolean);return visualAssets.ready;});
export function drawCell(g,image,columns,rows,index,x,y,w,h){if(!image)return false;const cw=image.naturalWidth/columns,ch=image.naturalHeight/rows;g.drawImage(image,(index%columns)*cw,Math.floor(index/columns)*ch,cw,ch,x,y,w,h);return true;}
export function drawScenery(g,kind,seed=0){const a=visualAssets.terrain;if(!a)return false;if(kind==='tree'){g.save();g.scale(seed%2?-1:1,1);drawCell(g,a,2,2,2,-68,-122,136,136);g.restore();return true;}if(['ruin','pillar','lighthouse','house'].includes(kind)){drawCell(g,a,2,2,3,-64,-114,128,128);return true;}return false;}
export function paintGardenTile(g,type,x,y){const a=visualAssets.terrain;if(!a||!['grass','path','stone'].includes(type))return false;g.save();g.transform(27/512,13.5/512,-27/512,13.5/512,x,y);drawCell(g,a,2,2,type==='grass'?0:1,0,0,512,512);g.restore();return true;}
export function drawWarriorSprite(g,moving,t,attack,a={}){if(!visualAssets.hero)return false;const frame=attack?8+Math.min(3,Math.floor((a.attackProgress||0)*4)):moving?4+Math.floor(t*9)%4:Math.floor(t*2)%4;g.save();const bob=moving?Math.sin(t*18)*.7:Math.sin(t*2)*.5;g.translate(0,bob);if(a.facingLeft)g.scale(-1,1);drawCell(g,visualAssets.hero,4,3,frame,-48,-122,96,128);g.restore();return true;}
export function drawWolfSprite(g,e,t){if(!visualAssets.wolf)return false;const frame=e.flash>0?8:e.winding>0?6+Math.floor(t*8)%2:e.moving?3+Math.floor(t*9)%3:Math.floor(t*2)%3;g.save();if(e.facing?.x+e.facing?.y<0)g.scale(-1,1);drawCell(g,visualAssets.wolf,3,3,frame,-45,-65,90,90);g.restore();return true;}

export const CLASS_CELLS={VIG:0,ESP:1,ARC:2,BAS:3,RUP:4,DUE:5,LAS:6};
export function drawClassSprite(g,id,moving,t,attack,a={}){
 if(!visualAssets.classes||CLASS_CELLS[id]===undefined||a.hasWeapon===false||a.hasArmor===false||a.hasSecondary===false&&id!=='RUP'||['hasHead','hasHands','hasLegs','hasBoots'].some(k=>a[k]===false))return false;
 g.save();if(a.facingLeft)g.scale(-1,1);const phase=a.attackProgress||0;
 g.translate(attack?Math.sin(phase*Math.PI)*4:0,moving?-Math.abs(Math.sin(t*9))*2:Math.sin(t*1.8)*.5);
 g.rotate(attack?Math.sin(phase*Math.PI)*.055:0);
 const ev=enchantVisual(a.enchant||0);g.shadowColor=ev.color;g.shadowBlur=ev.stage>=4?4:ev.stage>=2?2:0;if(id==='RUP'&&visualAssets.ruptorMotion){const frame=attack?8+Math.min(3,Math.floor(phase*4)):moving?4+Math.floor(t*8)%4:Math.floor(t*1.5)%4;drawCell(g,visualAssets.ruptorMotion,4,3,frame,-64,-122,128,128);}else if(attack&&visualAssets.attackMotion){const row={VIG:0,ESP:1,ARC:2,BAS:3,DUE:4,LAS:5}[id];drawCell(g,visualAssets.attackMotion,4,6,row*4+Math.min(3,Math.floor(phase*4)),-64,-122,128,128);}else drawCell(g,visualAssets.classes,4,2,CLASS_CELLS[id],-48,-122,96,128);g.shadowBlur=0;
 // Energy is attached to the same transform as the weapon and hand.
 const enchant=a.enchant||0;if(Math.max(enchant,a.secondaryEnchant||0)>=5){g.globalCompositeOperation='lighter';
 const paths={VIG:[[15,-60,42,-34],[-12,-89,-20,-59]],ESP:[[-37,-53,-15,-69],[24,-41,39,-57]],ARC:[[-29,-104,-28,-20],[25,-83,28,-76]],BAS:[[0,-50,37,-26],[-29,-67,-22,-32]],RUP:[[-3,-68,43,-18]],DUE:[[-35,-25,-10,-63],[19,-48,36,-22]],LAS:[[-19,-57,40,-33],[25,-81,28,-75]]};
 for(const [pathIndex,[x,y,ex,ey]] of paths[id].entries()){const ev=enchantVisual(pathIndex>0?(a.secondaryEnchant??enchant):enchant),c=ev.color;if(ev.stage===0)continue;for(let n=0;n<ev.motes;n++){const q=(t*(.3+ev.intensity*.4)+n/ev.motes)%1;g.globalAlpha=(.3+Math.sin(q*Math.PI)*.5)*Math.min(1,enchant/15);g.fillStyle=n%2?c:'#ffffff';g.beginPath();g.arc(x+(ex-x)*q,y+(ey-y)*q,1+n%2*.35,0,Math.PI*2);g.fill();}g.strokeStyle=c;g.lineWidth=1;g.globalAlpha=.12+ev.intensity*(.3+.15*Math.sin(t*3));g.beginPath();g.moveTo(x,y);g.lineTo(ex,ey);g.stroke();if(ev.stage>=4){g.lineWidth=ev.stage===5?5:3;g.globalAlpha=ev.stage===5?.18:.10;g.stroke();}if(ev.stage===5){for(let n=0;n<3;n++){const q=(t*.8+n/3)%1;g.globalAlpha=Math.sin(q*Math.PI)*.8;g.fillStyle=n%2?'#ffb5ff':'#cfffff';g.beginPath();g.arc(x+(ex-x)*q+Math.sin(t*9+n)*3,y+(ey-y)*q+Math.cos(t*9+n)*3,1.7,0,Math.PI*2);g.fill();}}}}
 g.restore();return true;
}
